"""Manual final dispositions for the pinned 307 contextual media candidates.

Visual recognition uses the actual hash-addressed source image as primary
observational evidence. It is distinguished from independently sourced historical
claims. Programme claims and unsupported interaction types are not admitted just
because their illustration matches the key.
"""
from editorial import digest


def decisions(rows):
    result={}
    def observed(i,note,**patch):
        row=rows[i-1]
        observations=[];evidence=[]
        for m in row['media']:
            if not m['file'] or m['semantic']['status']!='consistent':raise ValueError('Unreviewed source image')
            text=m['assessment'].get('note','')
            observations.append(text)
            evidence.append(dict(url='http://127.0.0.1:5188/library-media/'+m['file']['id'],
                note=f"Непосредственное наблюдение исходного файла ({m['phase']}, SHA-256 {m['file']['sha256']}): {text}",
                role='factual',status='pass',confidence='medium',snapshot_sha256=m['file']['sha256']))
        result[i]=dict(outcome='approved',basis='observed_media',note=note,
            patch=patch,evidence=evidence,media_note=note+' Файлы сопоставлены с окончательной формулировкой; исходные байты сохранены.')
    def visual(indices,note):
        for i in indices:observed(i,note)
    def game(indices,note,**patch):
        for i in indices:
            observed(i,note,truth_mode='game_convention',**patch)
            result[i]['basis']='game_convention'
            # Observations establish the clue and reveal; they are not proof of
            # literal truth for a meme, parody or deliberately absurd image.
            for e in result[i]['evidence']:e['role']='original'
    def fact(i,url,note,**patch):
        observed(i,note,**patch)
        result[i]['basis']='external_reference_and_media'
        result[i]['evidence'].append(dict(url=url,note=note,role='factual',status='pass',confidence='medium'))
